  </div>
{{/if}}

options.afterRender:
var el=context.element||context.grafana?.element; if(!el)return;
var root=el.querySelector('#p5-root'); if(!root)return;
var runs=[]; try{runs=JSON.parse(root.dataset.runs||'[]');}catch(e){}
var avgLbl=root.dataset.avg||'\u2014'; var maxLbl=root.dataset.max||'\u2014';
var canvas=el.querySelector('#p5-canvas'); if(!canvas)return;
var dpr=window.devicePixelRatio||1;
var W=(canvas.parentElement&&canvas.parentElement.offsetWidth>20)?canvas.parentElement.offsetWidth:500;
var H=380;
canvas.width=Math.round(W*dpr); canvas.height=Math.round(H*dpr);
canvas.style.width=W+'px'; canvas.style.height=H+'px';
var ctx=canvas.getContext('2d'); ctx.scale(dpr,dpr); ctx.clearRect(0,0,W,H);

function rr(x,y,w,h,r){
  r=Math.min(r,w/2,h/2);
  ctx.beginPath();
  ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r);
  ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
}

/* white card */
ctx.save(); ctx.shadowColor='rgba(0,0,0,0.10)'; ctx.shadowBlur=14; ctx.shadowOffsetY=2;
ctx.fillStyle='#ffffff'; rr(1,1,W-2,H-2,14); ctx.fill(); ctx.restore();
ctx.strokeStyle='#e5e7eb'; ctx.lineWidth=1; rr(1,1,W-2,H-2,14); ctx.stroke();

/* title */
ctx.fillStyle='#111827'; ctx.font='600 15px Inter,system-ui,sans-serif';
ctx.textAlign='left'; ctx.fillText('Export processing time',16,30);

/* subtitle */
ctx.fillStyle='#9ca3af'; ctx.font='12px Inter,system-ui,sans-serif';
ctx.fillText('Duration per attempt, in seconds',16,48);

/* avg/max */
ctx.textAlign='right'; ctx.font='600 13px Inter,system-ui,sans-serif';
ctx.fillStyle='#111827';
ctx.fillText('avg '+avgLbl+'s  \u00b7  max '+maxLbl+'s',W-16,30);
ctx.textAlign='left';

var n=runs.length;
if(!n){
  ctx.fillStyle='#9ca3af'; ctx.font='13px Inter,sans-serif';
  ctx.textAlign='center'; ctx.fillText('No data in selected time range',W/2,H/2);
  return;
}

var durs=runs.map(function(r){return parseFloat(r.duration_seconds)||0;});

/* chart area */
var cL=40,cR=W-16,cT=58,cB=H-66;
var cW=cR-cL,cH=cB-cT;

/* y-axis range: always 0 to at least 25, rounded up to next 5 */
var maxDur=Math.max.apply(null,durs);
var maxY=Math.max(25,Math.ceil((maxDur+2)/5)*5);

var tx=function(i){return n>1?cL+i/(n-1)*cW:cL+cW/2;};
var ty=function(v){return cB-v/maxY*cH;};

/* grid lines + y labels (every 5s) */
for(var v=0;v<=maxY;v+=5){
  var gy=Math.round(ty(v));
  ctx.strokeStyle='#f3f4f6'; ctx.lineWidth=1; ctx.setLineDash([]);
  ctx.beginPath(); ctx.moveTo(cL,gy); ctx.lineTo(cR,gy); ctx.stroke();
  ctx.fillStyle='#9ca3af'; ctx.font='10px Inter,sans-serif'; ctx.textAlign='right';
  ctx.fillText(v+'s',cL-6,gy+4);
}


/* gradient fill under line */
var grad=ctx.createLinearGradient(0,cT,0,cB);
grad.addColorStop(0,'rgba(59,130,246,0.18)');
grad.addColorStop(1,'rgba(59,130,246,0.01)');
ctx.beginPath(); ctx.moveTo(tx(0),ty(durs[0]));
for(var i=1;i<n;i++) ctx.lineTo(tx(i),ty(durs[i]));
ctx.lineTo(tx(n-1),cB); ctx.lineTo(tx(0),cB); ctx.closePath();
ctx.fillStyle=grad; ctx.fill();

/* line */
ctx.strokeStyle='#3b82f6'; ctx.lineWidth=2; ctx.lineJoin='round'; ctx.setLineDash([]);
ctx.beginPath();
for(var i=0;i<n;i++){if(i===0)ctx.moveTo(tx(i),ty(durs[i]));else ctx.lineTo(tx(i),ty(durs[i]));}
ctx.stroke();

/* success dots (blue, small) */
for(var i=0;i<n;i++){
  if(runs[i].status!=='failed'){
    ctx.fillStyle='#3b82f6'; ctx.strokeStyle='#93c5fd'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.arc(tx(i),ty(durs[i]),4,0,Math.PI*2);
    ctx.fill(); ctx.stroke();
  }
}

/* failed dots (red, larger, on top) */
for(var i=0;i<n;i++){
  if(runs[i].status==='failed'){
    ctx.fillStyle='#ef4444'; ctx.strokeStyle='#fca5a5'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.arc(tx(i),ty(durs[i]),4,0,Math.PI*2);
    ctx.fill(); ctx.stroke();
  }
}

/* x-axis line */
ctx.strokeStyle='#e5e7eb'; ctx.lineWidth=1; ctx.setLineDash([]);
ctx.beginPath(); ctx.moveTo(cL,cB); ctx.lineTo(cR,cB); ctx.stroke();

/* x-axis labels */
ctx.fillStyle='#9ca3af'; ctx.font='10px Inter,sans-serif'; ctx.textAlign='center';
var xPts=n<=1?[0]:n<=6?Array.from({length:n},function(_,i){return i;}):[0,Math.floor((n-1)/2),n-1];
var shown={};
xPts.forEach(function(i){
  if(shown[i])return; shown[i]=1;
  ctx.fillText(i+1,tx(i),cB+14);
});
ctx.fillStyle='#9ca3af'; ctx.font='11px Inter,sans-serif';
ctx.fillText('Attempt #',cL+cW/2,cB+28);

/* legend row */
var lgY=H-14, lgX=cL;
/* Duration line + dot */
ctx.strokeStyle='#3b82f6'; ctx.lineWidth=2; ctx.setLineDash([]);
ctx.beginPath(); ctx.moveTo(lgX,lgY-5); ctx.lineTo(lgX+18,lgY-5); ctx.stroke();
ctx.fillStyle='#3b82f6'; ctx.beginPath(); ctx.arc(lgX+9,lgY-5,4,0,Math.PI*2); ctx.fill();
ctx.fillStyle='#374151'; ctx.font='11px Inter,sans-serif'; ctx.textAlign='left';
ctx.fillText('Duration (s)',lgX+24,lgY);
/* Failed dot */
ctx.fillStyle='#ef4444'; ctx.beginPath(); ctx.arc(lgX+128,lgY-5,4,0,Math.PI*2); ctx.fill();
ctx.fillStyle='#374151'; ctx.fillText('Failed attempt',lgX+140,lgY);

list.definition:
SELECT CASE WHEN (u.is_admin OR EXISTS (
  SELECT 1 FROM team_member tm
  JOIN team t ON tm.team_id = t.id
  WHERE tm.user_id = u.id AND t.name LIKE '%\_ALL' ESCAPE '\'
)) THEN 1 ELSE 0 END
FROM "user" u WHERE u.id = ${__user.id}

